// W2d A14 (PR A's proof; plan "PR split", Task 14 without its API v1 half) — every W2d table seam of Tasks 0–12 driven
// through its REAL producer and its REAL consumer (AGENTS.md class 1, the inert seam): the stage is generated by the
// real `generateStageFixtures` (the pin, X-TB-2), each result is written by `scoreEvent` (the console's write) and
// folded by the real recompute (`recomputeStandings`, payout, `rankStandings`), and the table is read back through the
// public division read (`getPublicDivision` → `public_standings_v`) and, for the cut, the public qualification builder
// (`divisionQualification`). No pin, rule or snapshot is written by hand.
//
// Expected values come from the rulebook rows (FB-PT-1, IH-PT-1, CK-PT-1, TT-PT-1, HK-TB-1, BG-TB-3/B5, X-TB-2, BD-WO-1,
// BD-TB-1) and the engine's own declarations (a sport's variant cfg, its default order, its presets) — never from
// `payout` or the ranker. Each case states the counterfactual its numbers differ from, so a fold that dropped the seam
// reads differently. Real Postgres; skipped without DATABASE_URL.
import { afterAll, describe, expect, it, vi } from "vitest";

// `unstable_cache` is a Next server-runtime API with no incrementalCache outside a real request — passthrough, never a
// memoising double (the public read is cached in production; here every read is a fresh one).
vi.mock("next/cache", () => ({
  unstable_cache: (fn: (...args: unknown[]) => unknown) => fn,
  revalidateTag: vi.fn(),
}));

